package ru.neverland.townyelections;

import java.time.*;
import java.time.format.DateTimeFormatter;
import java.util.*;
import org.bukkit.Material;
import org.bukkit.entity.Player;
import org.bukkit.event.inventory.*;
import org.bukkit.inventory.*;
import ru.neverland.core.*;

/** Public campaign promises only; never shows individual ballots or writes a vote. */
final class ElectionProgramsMenu {
    private static final int[] CELLS={10,11,12,13,14,15,16,19,20,21,22,23,24,25,28,29,30,31,32,33,34,37,38,39,40,41,42,43};
    private static final DateTimeFormatter DATE=DateTimeFormatter.ofPattern("dd.MM.yyyy HH:mm 'МСК'").withZone(ZoneId.of("Europe/Moscow"));
    private final NeverLandTownyElections plugin;private final ElectionsService service;private final ElectionsMenus parent;
    static final class View implements InventoryHolder {final UUID town,candidate,campaign;final int page;boolean history;final Map<Integer,UUID> candidates=new HashMap<>(),campaigns=new HashMap<>();Inventory inventory;View(UUID town,UUID candidate,UUID campaign,int page){this.town=town;this.candidate=candidate;this.campaign=campaign;this.page=Math.max(0,page);}@Override public Inventory getInventory(){return inventory;}}
    ElectionProgramsMenu(NeverLandTownyElections plugin,ElectionsService service,ElectionsMenus parent){this.plugin=plugin;this.service=service;this.parent=parent;}
    private boolean allowed(Player p,UUID town){var own=ElectionsService.ownTown(p.getUniqueId());return p.hasPermission("townyelections.use")&&own!=null&&own.getUUID().equals(town);}
    void open(Player p,UUID candidate,int requestedPage)throws Exception{open(p,candidate,requestedPage,null);}
    void open(Player p,UUID candidate,int requestedPage,UUID campaign)throws Exception{try(var guard=SuiteState.guard()){
        var town=ElectionsService.requireTown(p);if(!allowed(p,town.getUUID()))throw new IllegalArgumentException("Нет доступа к программам своего города.");
        service.programs().refresh(town.getUUID(),campaign);var report=service.programs().report(town.getUUID(),campaign);var rows=new TreeMap<>(map(report.get("rows")));int pages=Math.max(1,(rows.size()+CELLS.length-1)/CELLS.length);int page=Math.min(Math.max(0,requestedPage),pages-1);
        var view=new View(town.getUUID(),candidate,campaign,page);view.inventory=MenuStyle.inventory(plugin,view,54,candidate==null?"Программы кандидатов":"Программа кандидата");
        view.inventory.setItem(48,item(Material.BELL,candidate==null?"К выборам города":"К программам кандидатов",List.of("Просмотр программы не меняет ваш голос.")));
        view.inventory.setItem(49,item(Material.SUNFLOWER,"Обновить сведения",List.of("Проверить цели по доступным данным города.")));
        if(!Boolean.TRUE.equals(report.get("available"))){boolean pending=Boolean.TRUE.equals(report.get("pending"));view.inventory.setItem(22,item(pending?Material.CLOCK:Material.BARRIER,pending?"Программы готовятся":"Программы пока недоступны",List.of(String.valueOf(report.getOrDefault("issue","Обновите окно немного позже.")),"Это не означает провал обещаний.","Голоса и выборы не изменены.")));p.openInventory(view.inventory);return;}
        boolean locked=Boolean.TRUE.equals(report.get("locked"));var header=new ArrayList<String>();header.add(locked?"Текст и цели закреплены для голосования.":"До начала голосования кандидат может изменить программу.");header.add(campaign==null?"Состояние целей проверяется по данным города.":"Архивная программа; показатели проверяются сейчас.");header.add("Недоступные сведения не считаются провалом.");header.add("Наград и автоматических наказаний нет.");view.inventory.setItem(4,item(Material.WRITTEN_BOOK,"Программы и проверка целей",header));
        if(candidate==null){
            var entries=new ArrayList<>(rows.entrySet());for(int i=page*CELLS.length;i<Math.min(entries.size(),(page+1)*CELLS.length);i++){
                UUID id;try{id=UUID.fromString(entries.get(i).getKey());}catch(IllegalArgumentException invalid){continue;}var row=map(entries.get(i).getValue());var lore=new ArrayList<String>();lore.add("Должность: "+race(row));lore.add("Проверяемых целей: "+list(row.get("promises")).size());lore.add("Опубликовано: "+date(row.get("submittedAt")));lore.addAll(wrap(String.valueOf(row.getOrDefault("statement","")),44,3));lore.add("Нажмите: программа и состояние каждой цели.");int slot=CELLS[i%CELLS.length];view.inventory.setItem(slot,item(Material.PAPER,name(row,id),lore));view.candidates.put(slot,id);
            }
            if(rows.isEmpty())view.inventory.setItem(22,item(Material.BOOK,"Программ пока нет",List.of("Кандидаты ещё не опубликовали проверяемые цели.","Это не мешает участию в выборах.")));
            if(page>0)view.inventory.setItem(45,item(Material.ARROW,"Предыдущая страница",List.of()));if(page+1<pages)view.inventory.setItem(53,item(Material.ARROW,"Следующая страница",List.of()));view.inventory.setItem(50,item(Material.PAPER,"Страница "+(page+1)+" / "+pages,List.of()));view.inventory.setItem(46,item(Material.CLOCK,"История программ",List.of("Закреплённые программы прошлых кампаний.")));view.inventory.setItem(51,item(Material.PLAYER_HEAD,"Моя программа",List.of("Открыть свои опубликованные цели.")));
        }else{
            var row=map(rows.get(candidate.toString()));if(row.isEmpty())view.inventory.setItem(22,item(Material.BOOK,"Программа не опубликована",List.of("У этого кандидата пока нет доступной программы.","Просмотр не меняет его участие в выборах.")));
            else{var speech=new ArrayList<String>();speech.add("Должность: "+race(row));speech.add("Опубликовано: "+date(row.get("submittedAt")));speech.addAll(wrap(String.valueOf(row.getOrDefault("statement","")),44,12));view.inventory.setItem(13,item(Material.WRITABLE_BOOK,name(row,candidate),speech));var promises=list(row.get("promises"));int[] places={29,31,33};for(int i=0;i<Math.min(3,promises.size());i++){var promise=map(promises.get(i));String status=String.valueOf(promise.getOrDefault("status","UNKNOWN"));var lore=new ArrayList<String>();lore.add("Цель: "+String.valueOf(promise.getOrDefault("target","не указана")));lore.add("При публикации: "+value(promise.get("baseline")));lore.add("Сейчас: "+value(promise.get("current")));lore.add(status(status));String issue=String.valueOf(promise.getOrDefault("issue",""));if(!issue.isBlank())lore.addAll(wrap(issue,44,4));lore.add("Проверено: "+date(promise.get("checkedAt")));lore.add("Показатель не доказывает личный вклад кандидата.");view.inventory.setItem(places[i],item(status.equals("MET")||status.equals("ALREADY_MET")?Material.LIME_DYE:status.equals("UNKNOWN")?Material.GRAY_DYE:Material.CLOCK,String.valueOf(promise.getOrDefault("title","Цель "+(i+1))),lore));}if(promises.isEmpty())view.inventory.setItem(31,item(Material.PAPER,"Проверяемых целей нет",List.of("Опубликован только текст программы.")));}
        }
        if(!locked&&p.hasPermission("townyelections.candidate"))view.inventory.setItem(52,item(Material.FEATHER,"Как изменить свою программу",List.of("Сначала выдвиньтесь в кандидаты.","Текст и до трёх проверяемых целей.","Нажмите: команды редактирования.","После начала голосования изменения закрыты.")));
        p.openInventory(view.inventory);
    }}
    void history(Player p,int requestedPage)throws Exception{try(var guard=SuiteState.guard()){var town=ElectionsService.requireTown(p);if(!allowed(p,town.getUUID()))throw new IllegalArgumentException("Нет доступа к программам своего города.");service.programs().refresh(town.getUUID());var report=service.programs().report(town.getUUID());var entries=list(report.get("history"));int pages=Math.max(1,(entries.size()+CELLS.length-1)/CELLS.length);int page=Math.min(Math.max(0,requestedPage),pages-1);var view=new View(town.getUUID(),null,null,page);view.history=true;view.inventory=MenuStyle.inventory(plugin,view,54,"История программ");view.inventory.setItem(4,item(Material.CLOCK,"Закреплённые программы",List.of("Сохранённые тексты и цели прошлых кампаний.","Показатели целей проверяются на момент просмотра.","Это не автоматическая оценка заслуг кандидата.")));view.inventory.setItem(48,item(Material.BELL,"К текущим программам",List.of()));view.inventory.setItem(49,item(Material.SUNFLOWER,"Обновить историю",List.of()));if(!Boolean.TRUE.equals(report.get("available"))&&!report.containsKey("history")){view.inventory.setItem(22,item(Material.BARRIER,"История пока недоступна",List.of(String.valueOf(report.getOrDefault("issue","Не удалось прочитать сохранённые программы.")))));p.openInventory(view.inventory);return;}if(entries.isEmpty())view.inventory.setItem(22,item(Material.BOOK,"Архивных программ пока нет",List.of("Они появляются после закрепления перед голосованием.")));for(int i=page*CELLS.length;i<Math.min(entries.size(),(page+1)*CELLS.length);i++){var entry=map(entries.get(i));UUID campaign;try{campaign=UUID.fromString(String.valueOf(entry.get("campaign")));}catch(IllegalArgumentException invalid){continue;}int slot=CELLS[i%CELLS.length];view.inventory.setItem(slot,item(Material.WRITTEN_BOOK,"Кампания · "+date(entry.get("at")),List.of("Нажмите: сохранённые программы кандидатов.","Цели не меняются после закрепления.")));view.campaigns.put(slot,campaign);}if(page>0)view.inventory.setItem(45,item(Material.ARROW,"Предыдущая страница",List.of()));if(page+1<pages)view.inventory.setItem(53,item(Material.ARROW,"Следующая страница",List.of()));view.inventory.setItem(50,item(Material.PAPER,"Страница "+(page+1)+" / "+pages,List.of()));p.openInventory(view.inventory);}}
    boolean click(InventoryClickEvent event){if(!(event.getView().getTopInventory().getHolder()instanceof View view))return false;event.setCancelled(true);if(!(event.getWhoClicked()instanceof Player p))return true;if(!allowed(p,view.town)){p.closeInventory();return true;}int slot=event.getRawSlot();if(slot<0||slot>=54||view.inventory.getItem(slot)==null)return true;
        SuiteScheduler.entity(plugin,p,()->{if(!p.isOnline()||p.getOpenInventory().getTopInventory()!=view.inventory)return;if(!allowed(p,view.town)){p.closeInventory();return;}try{if(view.campaigns.containsKey(slot))open(p,null,0,view.campaigns.get(slot));else if(view.candidates.containsKey(slot))open(p,view.candidates.get(slot),0,view.campaign);else if(slot==48){if(view.history)open(p,null,0);else if(view.candidate!=null)open(p,null,0,view.campaign);else if(view.campaign!=null)history(p,0);else parent.open(p,null,0,null,null);}else if(slot==49){if(view.history)history(p,view.page);else open(p,view.candidate,view.page,view.campaign);}else if(slot==45||slot==53){int page=view.page+(slot==45?-1:1);if(view.history)history(p,page);else open(p,null,page,view.campaign);}else if(slot==46)history(p,0);else if(slot==51)open(p,p.getUniqueId(),0,view.campaign);else if(slot==52)editingHelp(p);}catch(Exception error){p.sendMessage("§cПрограммы: "+error.getMessage());}});return true;
    }
    boolean drag(InventoryDragEvent event){if(!(event.getView().getTopInventory().getHolder()instanceof View))return false;event.setCancelled(true);return true;}
    static void editingHelp(Player p){p.sendMessage("§6Своя программа: §f/t elections promise text <текст>");p.sendMessage("§e/t elections promise building <ID здания> <уровень> §7— завершить здание");p.sendMessage("§e/t elections promise population <жителей> §7— увеличить население");p.sendMessage("§e/t elections promise pollution <предел> §7— снизить загрязнение");p.sendMessage("§e/t elections promise remove <1–3> §7— убрать цель; clear — очистить программу");p.sendMessage("§7Изменения доступны кандидату до голосования и действуют только после подтверждения сохранения.");}
    @SuppressWarnings("unchecked")private static Map<String,Object> map(Object value){return value instanceof Map<?,?> m?(Map<String,Object>)m:Map.of();}private static List<?> list(Object value){return value instanceof List<?> l?l:List.of();}
    private String race(Map<String,Object> row){return parent.name(String.valueOf(row.getOrDefault("race","")));}private static String name(Map<String,Object> row,UUID candidate){return String.valueOf(row.getOrDefault("name",ElectionsMenus.residentName(candidate)));}
    private static String value(Object value){if(value==null||String.valueOf(value).isBlank())return "нет подтверждённых данных";return String.valueOf(value);}
    private static String status(String status){return switch(status){case "MET"->"Цель достигнута по текущим данным.";case "ALREADY_MET"->"Условие уже выполнялось при публикации.";case "PENDING"->"По текущим данным цель пока не достигнута.";default->"Не хватает данных для проверки цели.";};}
    private static String date(Object value){return value instanceof Number n&&n.longValue()>0?DATE.format(Instant.ofEpochMilli(n.longValue())):"нет подтверждённых данных";}
    private static List<String> wrap(String text,int width,int maximum){if(text.isBlank())return List.of("Текст программы не добавлен.");var result=new ArrayList<String>();String rest=text.replace('\n',' ').replace('\r',' ').strip();while(!rest.isEmpty()&&result.size()<maximum){int cut=Math.min(width,rest.length());if(cut<rest.length()){int space=rest.lastIndexOf(' ',cut);if(space>0)cut=space;}result.add(rest.substring(0,cut));rest=rest.substring(cut).stripLeading();}if(!rest.isEmpty())result.set(result.size()-1,result.get(result.size()-1)+"…");return List.copyOf(result);}
    private static ItemStack item(Material material,String title,List<String> lore){var item=new ItemStack(material);var meta=item.getItemMeta();meta.setDisplayName(MenuStyle.nameLegacy("&b"+title));meta.setLore(MenuStyle.loreStrings(lore.stream().map(s->"&7"+s).toList()));meta.addItemFlags(ItemFlag.HIDE_ATTRIBUTES);item.setItemMeta(meta);return item;}
}
